const mastra = new Mastra({
  server: {
    onError: (err, c) => {
      // Log to Sentry
      Sentry.captureException(err);

      // Return custom formatted response
      return c.json({
        error: err.message,
        timestamp: new Date().toISOString(),
      }, 500);
    },
  },
});
