const mastra = new Mastra({
  idGenerator: (context) => {
    if (context?.idType === 'message' && context?.threadId) {
      return `msg-${context.threadId}-${Date.now()}`;
    }
    if (context?.idType === 'run' && context?.entityId) {
      return `run-${context.entityId}-${Date.now()}`;
    }
    return crypto.randomUUID();
  }
});
